# memcpy: its C stubs are generated by ctypes (Cstubs) at build time, with
# ocamlbuild, in a build opam does not keep: generated again here (by the
# host's generator: the C is the same for any target), then compiled.

SOURCE=opam:memcpy

build() {
  log "generating the ctypes stubs (host generator)"
  env -u OCAMLFIND_CONF -u OCAMLFIND_TOOLCHAIN -u CFLAGS -u CXXFLAGS -u LDFLAGS PATH="$HOST_BIN:$PATH" \
    CTYPES_LIB_DIR="$PREFIX/lib/ctypes" ocamlbuild -use-ocamlfind -classic-display lib/memcpy_stubs.c \
    > gen.log 2>&1 || { tail -30 gen.log; die "the ctypes generator failed"; }
  stub_cc _build/lib/memcpy_stubs.c -I"$PREFIX/lib/ctypes" || die "memcpy: cannot compile memcpy_stubs.c"
  mklib memcpy_stubs _build/lib/memcpy_stubs.o
  install_lib libmemcpy_stubs.a
  provides memcpy memcpy_stubs
}
